(function(){
"use strict";
const $ = (s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const lenis=null, reduce=window.matchMedia("(prefers-reduced-motion: reduce)").matches;
/* ================= CLUB COLMENA SIGN-UP ================= */
// Where sign-ups go. Set CLUB_EMAIL (opens the visitor's mail app) or CLUB_ENDPOINT (a form service URL that accepts POST).
const CLUB_EMAIL='', CLUB_ENDPOINT='/api/club/join';
const cm=$('#clubModal'), cf=$('#clubForm');
const openClub=()=>{cm.hidden=false;lenis&&lenis.stop();setTimeout(()=>cf.querySelector('input').focus(),50)};
const closeClub=()=>{cm.hidden=true;lenis&&lenis.start()};
$$('[data-club]').forEach(b=>b.addEventListener('click',openClub));
$$('[data-cclose]').forEach(b=>b.addEventListener('click',closeClub));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!cm.hidden)closeClub()});
cf.addEventListener('submit',async e=>{
  e.preventDefault(); const err=$('#clubErr'), d=Object.fromEntries(new FormData(cf)); err.classList.remove('info');
  if(!d.nombre||!d.nombre.trim()){err.textContent='Escribe tu nombre.';err.hidden=false;return}
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.correo||'')){err.textContent='Revisa tu correo electrónico.';err.hidden=false;return}
  if(!d.acepto){err.textContent='Acepta los términos para unirte.';err.hidden=false;return}
  err.hidden=true;
  if(CLUB_ENDPOINT){
    try{const r=await fetch(CLUB_ENDPOINT,{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify(d)});const j=await r.json().catch(()=>({}));
      if(!r.ok){err.textContent=j.error||'No pudimos enviar tus datos. Intenta de nuevo en un momento.';err.hidden=false;return}
      cf.innerHTML=j.number?'<div class="cdone"><h3>¡Bienvenido al BEE CLUB!</h3><p class="cmuted" style="margin-top:8px">Tu número de socio es</p><p style="font-size:28px;font-weight:800;letter-spacing:.04em;margin:6px 0">'+esc(String(j.number).replace(/^BEE/,'BEE-'))+'</p><p class="cmuted">Guárdalo y díctalo al reservar, en la web o con tu agencia, para sumar Puntos Miel después de cada vuelo.</p></div>'
        :'<div class="cdone"><h3>Ya eres parte del BEE CLUB</h3><p class="cmuted" style="margin-top:8px">El correo '+esc(d.correo)+' ya está inscrito. Si no recuerdas tu número de socio, escríbenos a management@beemoair.com.</p></div>';}
    catch(_){err.textContent='No pudimos enviar tus datos. Intenta de nuevo en un momento.';err.hidden=false}
  } else if(CLUB_EMAIL){
    location.href='mailto:'+CLUB_EMAIL+'?subject='+encodeURIComponent('Quiero unirme al BEE CLUB')+'&body='+encodeURIComponent('Nombre: '+d.nombre+'\nCorreo: '+d.correo+'\nTeléfono: '+(d.telefono||''));
  } else {
    err.textContent='Las inscripciones al BEE CLUB abren muy pronto. Aún no guardamos tus datos.';err.classList.add('info');err.hidden=false;
  }
});

// dialogs live inside <main>; move them to <body> so they sit above the fixed nav and logo
['clubModal','loginModal','acct'].forEach(id=>document.body.appendChild(document.getElementById(id)));

/* ================= LOGIN + MI CUENTA ================= */
// Real accounts need a backend. Set AUTH_ENDPOINT to a login API that returns the member JSON
// ({nombre, nivel, puntos, ...}). Until then only the clearly labelled demo account opens.
const AUTH_ENDPOINT='';
const DEMO={nombre:'Juanita Pérez',corto:'Juanita',nivel:'HoneyBee',sig:'GoldenBee',vuelos:4,meta:6,puntos:3420,entradas:2,
  proximo:{o:'MIA',d:'AXM',fecha:'Lun, 14 Dic 2026',hora:'09:40',vuelo:'BM 701',asiento:'12C'},
  canjes:[['Embarque prioritario',800],['Maleta adicional de 23 kg',1500],['Ascenso a Flex BC (un trayecto)',4000],['Vuelo Miami–Armenia (un trayecto)',20000]],
  historial:[['14 Dic 2026','Vuelo MIA–AXM · Flex',+730],['3 Nov 2026','Bono por unirte al BEE CLUB',+500],['18 Oct 2026','Vuelo AXM–MIA · Classic',+710],['18 Oct 2026','Canje: maleta adicional',-1500]]};
let member=null;
const lm=$('#loginModal'), lf=$('#loginForm'), acct=$('#acct'), ab=$('#acctBody');
const openLogin=()=>{if(member){openAcct();return} lm.hidden=false;lenis&&lenis.stop();setTimeout(()=>lf.querySelector('input').focus(),50)};
const closeLogin=()=>{lm.hidden=true;lenis&&lenis.start()};
$$('[data-login]').forEach(b=>b.addEventListener('click',openLogin));
$$('[data-lclose]').forEach(b=>b.addEventListener('click',closeLogin));
$('[data-club-from-login]').addEventListener('click',()=>{closeLogin();$('[data-club]').click()});
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if(!lm.hidden)closeLogin();else if(acct.classList.contains('open'))closeAcct()});
const lerr=(m,info)=>{const e=$('#loginErr');e.textContent=m;e.classList.toggle('info',!!info);e.hidden=false};
$('#forgot').addEventListener('click',()=>lerr('La recuperación de contraseña se activa cuando abran las cuentas del BEE CLUB.',true));
lf.addEventListener('submit',async e=>{
  e.preventDefault(); const d=Object.fromEntries(new FormData(lf));
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.correo||'')){lerr('Revisa tu correo electrónico.');return}
  if(!d.clave){lerr('Escribe tu contraseña.');return}
  if(!AUTH_ENDPOINT){lerr('Las cuentas del BEE CLUB se activan muy pronto. Mientras tanto puedes ver la cuenta de demostración.',true);return}
  try{const r=await fetch(AUTH_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:d.correo,password:d.clave})});
    if(r.status===401){lerr('El correo o la contraseña no coinciden.');return} if(!r.ok)throw 0;
    member=Object.assign({demo:false},await r.json()); lf.reset(); closeLogin(); openAcct();}
  catch(_){lerr('No pudimos iniciar sesión. Intenta de nuevo en un momento.')}
});
$('#demoLogin').addEventListener('click',()=>{member=Object.assign({demo:true},DEMO);closeLogin();openAcct()});
function openAcct(){renderAcct();acct.classList.add('open');acct.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';lenis&&lenis.stop();ab.focus()}
function closeAcct(){acct.classList.remove('open');acct.setAttribute('aria-hidden','true');document.body.style.overflow='';lenis&&lenis.start()}
$$('[data-aclose]').forEach(b=>b.addEventListener('click',closeAcct));
$('#logout').addEventListener('click',()=>{member=null;closeAcct();$('#navAcct span').textContent='Mi cuenta'});
const pts=n=>n.toLocaleString('es-CO');
function renderAcct(){
  const m=member; $('#navAcct span').textContent=m.corto||m.nombre;
  const pct=Math.min(100,Math.round(m.vuelos/m.meta*100)), falta=Math.max(0,m.meta-m.vuelos);
  ab.innerHTML=`${m.demo?'<p class="demo-banner"><b>Cuenta de demostración.</b> Así se verá tu cuenta cuando abran las inscripciones; los datos son de ejemplo.</p>':''}
  <div class="acct-hero">
    <div><p class="who">Hola, ${esc(m.corto||m.nombre)}</p><span class="lvl">Nivel ${esc(m.nivel)}</span></div>
    <div class="pts"><b>${pts(m.puntos)}</b><span>Puntos Miel</span></div>
    <div class="prog"><p>${falta?`Te faltan ${falta} ${falta>1?'vuelos':'vuelo'} este año para llegar a ${esc(m.sig)}`:`Ya eres ${esc(m.nivel)}`}</p><div class="bar3"><i style="width:${pct}%"></i></div></div>
  </div>
  <div class="acct-grid">
    <div class="acard"><h4>Tu próximo vuelo</h4>${m.proximo?`<div class="trip"><span>${m.proximo.o}</span><i></i><span>${m.proximo.d}</span></div><p class="muted">${esc(m.proximo.fecha)} · ${m.proximo.hora} · ${m.proximo.vuelo} · Asiento ${m.proximo.asiento}</p>`:'<p class="muted">No tienes vuelos reservados.</p>'}</div>
    <div class="acard"><h4>Sorteo de este mes</h4><p class="big">${m.entradas} ${m.entradas===1?'entrada':'entradas'}</p><p class="muted">Participas por un vuelo ida y vuelta Miami–Armenia.</p></div>
  </div>
  <div class="acard" style="margin-top:16px"><h4>Canjea tus Puntos Miel</h4><ul class="rlist">${m.canjes.map(([n,c])=>`<li><span>${esc(n)}</span><span style="display:flex;gap:12px;align-items:center"><span class="cost">${pts(c)} pts</span><button ${c>m.puntos?'disabled':''} data-redeem="${esc(n)}">${c>m.puntos?'Te faltan puntos':'Canjear'}</button></span></li>`).join('')}</ul><p class="formerr info" id="redeemMsg" hidden></p></div>
  <div class="acard" style="margin-top:16px"><h4>Movimientos</h4><table class="hist" style="width:100%;border-collapse:collapse">${m.historial.map(([f,t,v])=>`<tr><td style="color:var(--ink-soft);width:110px">${f}</td><td>${esc(t)}</td><td class="${v>0?'plus':''}">${v>0?'+':''}${pts(v)}</td></tr>`).join('')}</table></div>`;
  $('#acctFoot').innerHTML=`<b>${pts(m.puntos)}</b>Puntos Miel disponibles`;
  $$('[data-redeem]',ab).forEach(b=>b.addEventListener('click',()=>{const r=$('#redeemMsg');r.hidden=false;
    r.textContent=m.demo?'En la cuenta de demostración no se canjean puntos.':'Recibimos tu solicitud de canje. Te confirmaremos por correo.'}));
}


})();
/* ================= V2: menu, help center, manage booking, quotes ================= */
(function(){
const EMAIL='management@beemoair.com';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const L=()=>window.__lenis||null;
const lock=()=>{try{L()&&L().stop()}catch(e){}}, unlock=()=>{try{L()&&L().start()}catch(e){}};
const scrollToSel=sel=>{const t=document.querySelector(sel); if(!t) return; try{ L()?L().scrollTo(t,{offset:-72}):t.scrollIntoView({behavior:'smooth'}) }catch(e){ t.scrollIntoView() }};
const clearHash=()=>{ if(location.hash) history.replaceState(null,'',location.pathname+location.search) };
const mailto=(subject,lines)=>{ location.href='mailto:'+EMAIL+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(lines.join('\n')) };
const okEmail=v=>/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v);
const showErr=(f,msg)=>{const e=f.querySelector('.formerr'); e.textContent=msg; e.classList.remove('info'); e.hidden=!msg};
const showInfo=(f,msg)=>{const e=f.querySelector('.formerr'); e.textContent=msg; e.classList.add('info'); e.hidden=false};
// move overlays to body (escape main stacking contexts)
['mnav','help','manage','quote'].forEach(id=>{const el=document.getElementById(id); if(el) document.body.appendChild(el)});

/* --- mobile menu --- */
const mnav=$('#mnav'), mbtn=$('#menuBtn');
const openMenu=()=>{mnav.hidden=false; mbtn.setAttribute('aria-expanded','true'); lock(); setTimeout(()=>mnav.querySelector('a').focus(),30)};
const closeMenu=()=>{mnav.hidden=true; mbtn.setAttribute('aria-expanded','false'); unlock()};
mbtn.addEventListener('click',openMenu);
$$('[data-mclose]',mnav).forEach(b=>b.addEventListener('click',closeMenu));
$$('[data-login]',mnav).forEach(b=>b.addEventListener('click',()=>{mnav.hidden=true; mbtn.setAttribute('aria-expanded','false')}));

/* --- help center --- */
const help=$('#help'), helpDoc=$('#helpDoc');
function openHelp(id){ if(!help) return;
  const docs=$$('.doc',help); if(!docs.some(d=>d.dataset.doc===id)) id='faq';
  docs.forEach(d=>d.hidden=d.dataset.doc!==id);
  $$('[data-doclink]',help).forEach(a=>{ if(a.dataset.doclink===id) a.setAttribute('aria-current','page'); else a.removeAttribute('aria-current') });
  const wasHidden=help.hidden; help.hidden=false; if(wasHidden) lock();
  helpDoc.scrollTop=0; helpDoc.focus({preventScroll:true});
  const cur=help.querySelector('[aria-current="page"]'); if(cur&&cur.scrollIntoView) cur.scrollIntoView({block:'nearest',inline:'nearest'});
}
const closeHelp=()=>{ if(!help) return; help.hidden=true; unlock(); clearHash() };
if(help){ $$('[data-hclose]',help).forEach(b=>b.addEventListener('click',closeHelp));
help.addEventListener('click',e=>{ if(e.target===help) closeHelp() }); }

/* --- Beemo API + season pass (server) --- */
const PCODES='beemo-pass-codes';
const myCodes=()=>{try{return JSON.parse(localStorage.getItem(PCODES)||'[]')}catch(e){return[]}};
const jget=async(u,o)=>{const r=await fetch(u,o);let j={};try{j=await r.json()}catch(e){};if(!r.ok){const e=new Error(j.error||'No pudimos conectar con Beemo Air. Intenta de nuevo en un momento.');e.data=j;e.status=r.status;throw e}return j};
window.BeemoAPI={get:u=>jget('/api'+u),post:(u,b)=>jget('/api'+u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)})};
window.BeemoPass={
  codes:myCodes,
  get:code=>window.BeemoAPI.get('/passes/'+encodeURIComponent(String(code||'').trim().toUpperCase())),
  products:()=>window.BeemoAPI.get('/pass-products'),
  isEn:()=>document.documentElement.lang==='en',
  money(n,dec){const en=document.documentElement.lang==='en';return 'US$'+Number(n).toLocaleString(en?'en-US':'es-CO',dec?{minimumFractionDigits:2,maximumFractionDigits:2}:{maximumFractionDigits:0})},
  pick:(o,k)=>document.documentElement.lang==='en'&&o[k+'_en']?o[k+'_en']:o[k],
  async buy(product_id,name,email){const j=await window.BeemoAPI.post('/passes',{product_id,name,email});const c=myCodes().filter(x=>x!==j.code);c.unshift(j.code);try{localStorage.setItem(PCODES,JSON.stringify(c.slice(0,10)))}catch(e){}return j}
};

/* --- home: season pass band from the admin catalog --- */
(function(){const box=document.getElementById('pbOffers'); if(!box) return; const band=box.closest('.pass-band'); let items=[];
  const draw=()=>{const BP=window.BeemoPass,en=BP.isEn(); box.innerHTML=items.slice(0,2).map(p=>`<a href="pase-de-temporada/#comprar"><b>${BP.pick(p,'name')}</b><span>${BP.money(p.price)}</span><em>${p.savings?(en?'You save ':'Ahorras ')+BP.money(p.savings):(en?'See details':'Ver detalles')}</em></a>`).join('')};
  window.BeemoPass.products().then(r=>{items=r.filter(p=>p.status==='active');if(!items.length)return;draw();band.hidden=false;
    new MutationObserver(draw).observe(document.documentElement,{attributes:true,attributeFilter:['lang']})}).catch(()=>{});
})();

/* --- manage booking --- */
const mg=$('#manage'), mgForm=$('#mgForm'), mgOut=$('#mgOut');
const norm=t=>String(t||'').normalize('NFD').replace(/[̀-ͯ]/g,'').trim().toLowerCase();
const getBk=()=>{try{return JSON.parse(localStorage.getItem('beemo-bookings')||'[]')}catch(e){return[]}};
const escH=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dLong=new Intl.DateTimeFormat('es',{weekday:'long',day:'numeric',month:'long'});
function openManage(){ mg.hidden=false; mgForm.hidden=false; mgOut.hidden=true; mgOut.innerHTML=''; showErr(mgForm,''); lock(); setTimeout(()=>mgForm.pnr.focus(),40) }
const closeManage=()=>{ mg.hidden=true; unlock(); clearHash() };
$$('[data-mgclose]',mg).forEach(b=>b.addEventListener('click',closeManage));
const FN={light:'Light',basic:'Basic',classic:'Classic',plus:'Plus',flex:'Flex',bc:'Flex BC'}, FRT={light:699,basic:799,classic:850,plus:980,flex:1050,bc:1550}, FRK={light:0,basic:1,classic:2,plus:3,flex:4,bc:5};
const srv2rec=(v,last)=>({pnr:v.pnr,last,status:v.status,expires:v.expires,pay_url:v.pay_url,due:v.due,
  legs:v.legs.map(l=>({route:l.route,date:l.date,dep:l.dep,arr:l.arr,no:l.no,fare:FN[l.fare],fk:l.fare,ex:l.extras,seats:l.seats})),
  pax:v.pax.map(p=>p.first+' '+p.last),
  adds:v.addons.filter(a=>a.status!=='cancelled').reduce((o,a)=>{(o[a.leg]=o[a.leg]||{})[a.key]=a.status;return o},{}),
  passes:(getBk().find(r=>r.pnr===v.pnr)||{}).passes||''});
mgForm.addEventListener('submit',async e=>{e.preventDefault();
  const code=mgForm.pnr.value.trim().toUpperCase(), last=mgForm.last.value.trim();
  if(code.length!==6) return showErr(mgForm,'Escribe el código de reserva de 6 caracteres.');
  if(!last) return showErr(mgForm,'Escribe el apellido del pasajero.');
  try{const v=await window.BeemoAPI.get('/bookings/'+code+'?last='+encodeURIComponent(last)); showErr(mgForm,''); renderBooking(srv2rec(v,last))}
  catch(err){showErr(mgForm,err.message)}
});
function legStatus(l){
  const [y,m,d]=l.date.split('-').map(Number), [h,mi]=l.dep.split(':').map(Number);
  const dep=new Date(y,m-1,d,h,mi), now=Date.now(), open=dep-72*3600e3, close=dep-3*3600e3;
  if(now<open){ const o=new Date(open); return {state:'soon', text:`El check-in abre el ${dLong.format(o)} a las ${String(o.getHours()).padStart(2,'0')}:${String(o.getMinutes()).padStart(2,'0')}.`} }
  if(now<=close) return {state:'open', text:'Check-in abierto'};
  if(now<dep) return {state:'closed', text:'El check-in en línea cerró. Acércate al mostrador del aeropuerto.'};
  return {state:'done', text:'Vuelo realizado'};
}
/* add-ons after booking: price ladder from doc 09 (hasta 7 días antes · hasta 24 h antes · aeropuerto) */
const LADDER={hand:[25,30,35],bag:[55,65,75],bag2:[65,75,90],front:[25,30,40],prio:[10,12,15],chg:[175,175,200]};
const ADDN={hand:['Equipaje de mano 10 kg','Por pasajero.'],bag:['Maleta de bodega 23 kg','Por pasajero.'],bag2:['Segunda maleta 23 kg','Por pasajero.'],front:['Asiento delantero o de salida de emergencia','Por pasajero. Te reasignamos en las filas 4 a 6, 13 o 14.'],
  prio:['Embarque prioritario','Por pasajero.'],flex:['Pasar a Flex','Por pasajero, la diferencia de tarifa. Maleta de 30 kg, asiento incluido y cambios sin cargo.'],biz:['Pasar a Business (Flex BC)','Por pasajero, la diferencia de tarifa. Sujeto a sillas libres en la cabina de 12 asientos.']};
const money0=n=>'US$'+n.toLocaleString('es-CO');
function addOns(rec){
  if(!rec.legs.some(l=>l.fk)) return '';
  const now=Date.now(); let rows='';
  rec.legs.forEach((l,li)=>{ if(!l.fk) return;
    const [y,m,d]=l.date.split('-').map(Number), [h,mi]=l.dep.split(':').map(Number), dep=new Date(y,m-1,d,h,mi), hrs=(dep-now)/36e5;
    if(hrs<=0) return; const w=hrs>168?0:hrs>24?1:2, airport=w===2, ad=(rec.adds&&rec.adds[li])||{};
    const exAll=k=>(l.ex||[]).filter(x=>x&&x[k]).length>=rec.pax.length, hasBag=ad.bag||exAll('bag');
    const rk=FRK[l.fk]??2, nob=l.fk==='light'||l.fk==='basic', up=k=>Math.max(0,(FRT[k]-FRT[l.fk])/2);
    const keys=(l.fk==='bc'?[]:['hand','bag','bag2','front','prio','flex','biz'])
      .filter(k=>!(k==='hand'&&(l.fk!=='light'||exAll('hand')))&&!(k==='bag'&&(!nob||exAll('bag')))&&!(k==='bag2'&&(exAll('bag2')||(nob&&!hasBag)))&&!(k==='front'&&rk>=5)&&!(k==='prio'&&exAll('prio'))&&!(k==='flex'&&rk>=4));
    const next=w===0?new Date(dep-168*36e5):w===1?new Date(dep-24*36e5):null;
    const [o,dd]=l.route.split('-');
    rows+=`<div class="mg-add-leg"><h5>${o} → ${dd}</h5>${!keys.length?'<p class="fine">Tu tarifa Flex BC ya incluye dos maletas, Business y embarque prioritario.</p>':''}`+keys.map(k=>{const p=k==='flex'?up('flex'):k==='biz'?up('bc'):LADDER[k][w], got=ad[k];
      return `<div class="mg-add"><div><b>${ADDN[k][0]}</b><small>${ADDN[k][1]}</small></div><div class="mg-add-r"><span class="mg-p">${p==null?'—':money0(p)}</span>${got?`<span class="mg-ok">${got==='pending'?'Agregado · por pagar':'Agregado'}</span>`:p==null||airport?`<span class="fine">${p==null?'No disponible':'Solo en el aeropuerto'}</span>`:`<button type="button" class="btn btn-ghost mg-btn" data-add="${li}:${k}">Agregar</button>`}</div></div>`}).join('')+
      (l.fk==='light'?`<div class="mg-add"><div><b>Cambio de fecha</b><small>Tu tarifa Light no permite cambios. Pasa a otra tarifa para poder cambiar la fecha.</small></div></div>`:l.fk==='basic'||l.fk==='classic'?`<div class="mg-add"><div><b>Cambio de fecha</b><small>Penalidad más la diferencia de tarifa, si la hay.</small></div><div class="mg-add-r"><span class="mg-p">${money0(LADDER.chg[w])}</span><button type="button" class="btn btn-ghost mg-btn" data-chg="${li}" data-fee="${money0(LADDER.chg[w])}">Solicitar</button></div></div>`:
        `<div class="mg-add"><div><b>Cambio de fecha</b><small>${l.fk==='plus'?'Un cambio sin cargo con tu tarifa Plus, más la diferencia de tarifa si la hay.':'Sin cargo con tu tarifa, más la diferencia de tarifa si la hay.'}</small></div><div class="mg-add-r"><button type="button" class="btn btn-ghost mg-btn" data-chg="${li}" data-fee="US$0">Solicitar</button></div></div>`)+
      (next?`<p class="mg-next">Estos precios suben el <span>${dLong.format(next)}</span>.</p>`:'')+`</div>`});
  if(!rows) return '';
  return `<div class="mg-adds" id="mgAdds"><h4>Agrega a tu viaje</h4><p class="fine">Precios por pasajero y por trayecto. Lo que agregues queda por pagar en tu reserva.</p>${rows}</div>`;
}
function renderBooking(rec){
  const st=rec.legs.map(legStatus), live=rec.status==='confirmed', anyOpen=live&&st.some(x=>x.state==='open');
  mgOut.innerHTML=`<div class="mg-res">
   <div class="mg-code"><span>Código de reserva</span><b>${escH(rec.pnr)}</b></div>
   <p class="mg-pax">${rec.pax.map(escH).join(' · ')}</p>
   ${rec.status==='pending'?`<p class="mg-st soon">Pendiente de pago. Tus sillas están apartadas hasta el <span>${dLong.format(new Date(rec.expires))}</span>.</p>${rec.pay_url?`<a class="btn btn-lime" href="${escH(rec.pay_url)}" style="padding:13px">Pagar ahora</a>`:''}`:''}
   ${rec.status==='cancelled'||rec.status==='expired'?`<p class="mg-st closed">${rec.status==='cancelled'?'Esta reserva fue anulada.':'Esta reserva venció sin pago y las sillas se liberaron.'}</p>`:''}
   ${rec.status==='confirmed'&&rec.due>0?`<p class="mg-st soon">Tienes extras por pagar: <b>US$${rec.due}</b>. Te enviaremos el enlace de pago por correo.</p>`:''}
   ${rec.legs.map((l,i)=>{const [o,d]=l.route.split('-');return `<div class="mg-leg"><div class="od">${o} → ${d}</div><div class="meta"><span>${dLong.format(new Date(l.date+'T12:00'))}</span> · <span>${l.dep}–${l.arr}</span> · <span>${escH(l.no)}</span> · <span>${escH(l.fare)}</span></div>${live?`<p class="mg-st ${st[i].state}">${st[i].text}</p>`:''}</div>`}).join('')}
   ${anyOpen?'<button type="button" class="btn btn-lime" id="mgCheck" style="padding:15px">Hacer check-in</button>':''}
   ${rec.status==='confirmed'||rec.status==='pending'?addOns(rec):''}
   <p class="formerr" id="mgErr" role="alert" hidden></p>
   <div class="mg-passes" id="mgPasses" hidden></div>
   <button type="button" class="linkbtn dark" id="mgAgain">Buscar otra reserva</button>
  </div>`;
  mgForm.hidden=true; mgOut.hidden=false;
  $('#mgAgain').addEventListener('click',openManage);
  $$('[data-add]',mgOut).forEach(b=>b.addEventListener('click',async()=>{const [li,k]=b.dataset.add.split(':'); b.disabled=true;
    try{const v=await window.BeemoAPI.post('/bookings/'+rec.pnr+'/addons',{last:rec.last,leg:+li,key:k}); renderBooking(srv2rec(v,rec.last)); const o=$('#mgAdds'); o&&o.scrollIntoView({block:'nearest'})}
    catch(err){b.disabled=false; const e=$('#mgErr'); e.textContent=err.message; e.hidden=false}}));
  $$('[data-chg]',mgOut).forEach(b=>b.addEventListener('click',()=>{const l=rec.legs[+b.dataset.chg];
    mailto('Cambio de fecha · '+rec.pnr,['Código de reserva: '+rec.pnr,'Trayecto: '+l.route+' · '+l.date,'Tarifa: '+l.fare,'Cargo por cambio: '+b.dataset.fee,'','Nueva fecha deseada:'])}));
  const c=$('#mgCheck'); if(c) c.addEventListener('click',()=>{ const p=$('#mgPasses'); p.innerHTML=rec.passes?'<h4>Tus pases de abordar</h4>'+rec.passes:'<p class="fine">Hiciste check-in. Tus pases de abordar te llegan al correo de la reserva.</p>'; p.hidden=false; c.remove() });
}

/* --- quotes --- */
const qm=$('#quote'), qf=$('#quoteForm');
let closeQuote=()=>{};
if(qf){
const TYPE={grupo:'Viaje en grupo',charter:'Vuelo chárter completo',carga:'Carga o encomienda'};
function openQuote(kind){ qm.hidden=false; if(kind) qf.tipo.value=kind; showErr(qf,''); lock(); setTimeout(()=>qf.nombre.focus(),40) }
closeQuote=()=>{ qm.hidden=true; unlock() };
$$('[data-quote]').forEach(b=>b.addEventListener('click',()=>openQuote(b.dataset.quote)));
$$('[data-qclose]',qm).forEach(b=>b.addEventListener('click',closeQuote));
qf.addEventListener('submit',e=>{e.preventDefault();
  if(!qf.nombre.value.trim()) return showErr(qf,'Escribe tu nombre.');
  if(!okEmail(qf.correo.value.trim())) return showErr(qf,'Revisa tu correo electrónico.');
  const t=TYPE[qf.tipo.value];
  mailto('Cotización Beemo Air: '+t,['Tipo: '+t,'Nombre: '+qf.nombre.value,'Correo: '+qf.correo.value,'Empresa: '+qf.empresa.value,'Fecha estimada: '+qf.fecha.value,'Personas o peso: '+qf.cantidad.value,'','Detalles:',qf.detalle.value]);
  showInfo(qf,'Abrimos tu correo con la solicitud lista. Si no se abrió, escríbenos a '+EMAIL+'.');
});
}

/* --- PQRS --- */
const pf=$('#pqrsForm');
if(pf) pf.addEventListener('submit',e=>{e.preventDefault();
  if(!pf.nombre.value.trim()) return showErr(pf,'Escribe tu nombre.');
  if(!okEmail(pf.correo.value.trim())) return showErr(pf,'Revisa tu correo electrónico.');
  if(pf.msg.value.trim().length<10) return showErr(pf,'Cuéntanos con más detalle qué pasó.');
  const d=new Date(), rad='PQ-'+String(d.getFullYear()).slice(2)+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0')+'-'+Math.random().toString(36).slice(2,6).toUpperCase();
  mailto('PQRS '+pf.tipo.value+' · '+rad,['Radicado: '+rad,'Tipo: '+pf.tipo.value,'Nombre: '+pf.nombre.value,'Correo: '+pf.correo.value,'Código de reserva: '+pf.pnr.value,'','Mensaje:',pf.msg.value]);
  showInfo(pf,'Tu número de radicado es '+rad+'. Abrimos tu correo con la solicitud lista para enviar.');
});

/* --- routing --- */
function route(){
  const h=decodeURIComponent(location.hash||'');
  if(h==='#mi-reserva'){ if(help&&!help.hidden){help.hidden=true} openManage(); return true }
  if(help&&h.startsWith('#ayuda')){ openHelp(h.split('/')[1]||'faq'); return true }
  return false;
}
window.addEventListener('hashchange',route);
document.addEventListener('click',e=>{
  const a=e.target.closest('a[href^="#"]'); if(!a||a.closest('.nav ul')||a.classList.contains('home')||a.getAttribute('href')==='#intro') return;
  const h=a.getAttribute('href');
  if(a.hasAttribute('data-mlink')) closeMenu();
  if(h==='#mi-reserva'||(help&&h.startsWith('#ayuda'))){ e.preventDefault(); if(location.hash===h) route(); else location.hash=h; return }
  if(h.length>1 && document.querySelector(h) && !a.closest('.help')){ e.preventDefault(); if(!mg.hidden) closeManage(); scrollToSel(h) }
});
document.addEventListener('keydown',e=>{ if(e.key!=='Escape') return;
  if(qm&&!qm.hidden) closeQuote(); else if(!mg.hidden) closeManage(); else if(help&&!help.hidden) closeHelp(); else if(!mnav.hidden) closeMenu(); });
if(location.hash) setTimeout(route,400);
})();

/* ---------- Embajadores: código de referido y red social ---------- */
window.BeemoRef=(()=>{const K='beemo-ref',AL={ig:'instagram',insta:'instagram',tt:'tiktok',yt:'youtube',fb:'facebook',twitter:'x',wa:'whatsapp'};
  const en=()=>(document.documentElement.lang||'').startsWith('en');
  const read=()=>{try{const r=JSON.parse(localStorage.getItem(K)||'null');if(r&&r.exp>Date.now())return r;localStorage.removeItem(K)}catch(e){}return null};
  const save=(r,days)=>{r.exp=Date.now()+(days||30)*864e5;try{localStorage.setItem(K,JSON.stringify(r))}catch(e){}return r};
  async function check(code,src){code=String(code||'').trim().toUpperCase();const cur=read();
    const r=await window.BeemoAPI.get('/ref/'+encodeURIComponent(code));
    if(!r.ok) throw new Error(en()?'That ambassador code does not exist or is no longer active.':'Ese código de embajador no existe o ya no está activo.');
    if(src==null) src=cur&&cur.code===r.code?cur.src:'';
    return save({code:r.code,name:r.name,src:src||''},r.window_days)}
  try{const u=new URLSearchParams(location.search),c=(u.get('ref')||u.get('codigo')||'').trim();
    if(c){let src=(u.get('red')||u.get('utm_source')||'').toLowerCase().trim();src=AL[src]||src||'otro';
      check(c,src).catch(()=>{});['ref','codigo','red','utm_source'].forEach(k=>u.delete(k));
      history.replaceState(null,'',location.pathname+(u.toString()?'?'+u:'')+location.hash)}}catch(e){}
  return {get:()=>{const r=read();return r?{code:r.code,src:r.src||''}:null},info:read,check,clear:()=>{try{localStorage.removeItem(K)}catch(e){}}}})();



