function trCore(s){
  if(EN[s]!=null) return EN[s];
  let out=null;
  for(const [re,rep] of RX){ if(re.test(s)){ out=s.replace(re,rep); break; } }
  let t=out==null?s:out;
  for(const [re,rep] of GEN) t=t.replace(re,rep);
  return (out!=null||t!==s)?t:null;
}
let LANG='es';
function tr(s){
  if(LANG==='es') return s;
  const m=s.match(/^(\s*)([\s\S]*?)(\s*)$/); const core=m[2].replace(/\s+/g,' ');
  if(!core||!/[A-Za-zÁÉÍÓÚáéíóúñ]/.test(core)) { const g=trCore(core); return g==null?s:m[1]+g+m[3]; }
  const r=trCore(core); return r==null?s:m[1]+r+m[3];
}
function trA(s){ if(LANG==='es') return s; const r=EN['@'+s]; if(r!=null) return r; const c=trCore(s); return c==null?s:c; }
const TXT=new WeakMap(), ATT=new WeakMap(), ATTRS=['aria-label','placeholder','title','alt'];
const skip=el=>!el||el.closest('script,style,[data-noi18n]');
function doText(n){
  if(skip(n.parentElement)) return;
  const rec=TXT.get(n), cur=n.nodeValue, o=(rec&&cur===rec.t)?rec.o:cur, t=tr(o);
  if(t!==cur) n.nodeValue=t; TXT.set(n,{o,t});
}
function doAttrs(el){
  if(skip(el)) return; let rec=ATT.get(el); if(!rec){rec={};ATT.set(el,rec)}
  for(const a of ATTRS){ if(!el.hasAttribute(a)) continue; const cur=el.getAttribute(a); if(cur.startsWith('data:')) continue;
    const r=rec[a], o=(r&&cur===r.t)?r.o:cur, t=trA(o); if(t!==cur) el.setAttribute(a,t); rec[a]={o,t}; }
}
function walk(root){
  if(root.nodeType===3){ doText(root); return; }
  if(root.nodeType!==1) return;
  doAttrs(root);
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);
  let n; while(n=w.nextNode()){ if(n.nodeType===3) doText(n); else doAttrs(n); }
}
let busy=false;
const mo=new MutationObserver(list=>{ if(busy) return; busy=true;
  try{ for(const m of list){
    if(m.type==='childList') m.addedNodes.forEach(walk);
    else if(m.type==='characterData') doText(m.target);
    else if(m.type==='attributes') doAttrs(m.target);
  } } finally { busy=false; } });
const TITLE={es:document.title,en:document.documentElement.dataset.titleEn||'Beemo Air — The miracle that brings us together'};
function setLang(l,save){
  LANG=l==='en'?'en':'es';
  document.documentElement.lang=LANG;
  document.title=TITLE[LANG];
  busy=true; try{ walk(document.body); } finally { busy=false; }
  document.querySelectorAll('[data-lang]').forEach(b=>{ b.innerHTML=LANG==='es'?"<svg class=\"flag\" viewBox=\"0 0 19 10\" aria-hidden=\"true\"><rect width=\"19\" height=\"10\" fill=\"#B22234\"/><path d=\"M0 1.15h19M0 2.7h19M0 4.23h19M0 5.77h19M0 7.3h19M0 8.85h19\" stroke=\"#fff\" stroke-width=\".77\"/><rect width=\"7.6\" height=\"5.38\" fill=\"#3C3B6E\"/></svg><span>EN</span>":"<svg class=\"flag\" viewBox=\"0 0 3 2\" aria-hidden=\"true\"><rect width=\"3\" height=\"2\" fill=\"#CE1126\"/><rect width=\"3\" height=\"1.5\" fill=\"#003893\"/><rect width=\"3\" height=\"1\" fill=\"#FCD116\"/></svg><span>ES</span>"; b.setAttribute('aria-label',LANG==='es'?'English':'Español'); b.setAttribute('lang',LANG==='es'?'en':'es'); ATT.delete(b); });
  if(save){ try{ localStorage.setItem('beemo-lang',LANG) }catch(e){} }
  try{ if(typeof layoutIntro==='function') layoutIntro(); if(window.ScrollTrigger) ScrollTrigger.refresh(); }catch(e){}
}
window.beemoLang={set:setLang,get:()=>LANG,tr};
let init='es';
